"""Mid-sparsity gap analysis for bf16_importance_s015 and bf16_importance_s025."""
import json
import numpy as np
from pathlib import Path
from collections import Counter
from scipy.stats import mannwhitneyu, trim_mean

BASE = Path("/root/autodl-tmp/pacs")
DATA_PATH = BASE / "data" / "math500.json"
EXPERIMENTS = {
    "bf16_importance_s015": BASE / "profiling_output_bf16_ds_imp_s015" / "profiling_results.json",
    "bf16_importance_s025": BASE / "profiling_output_bf16_ds_imp_s025" / "profiling_results.json",
}

def load_math500_metadata():
    with open(DATA_PATH) as f:
        return {p["id"]: p for p in json.load(f)}

def load_per_problem_ii(path):
    with open(path) as f:
        data = json.load(f)
    ppi = data["per_problem_ii"]
    level = list(ppi.keys())[0]
    return ppi[level], data

def bootstrap_median_ci(values, n_boot=10000, seed=42):
    rng = np.random.RandomState(seed)
    arr = np.array(values)
    n = len(arr)
    if n < 2:
        return {"median": float(np.median(arr)) if n > 0 else None, "ci_low": None, "ci_high": None}
    boots = np.array([np.median(arr[rng.randint(0, n, n)]) for _ in range(n_boot)])
    return {"median": float(np.median(arr)), "ci_low": float(np.percentile(boots, 2.5)), "ci_high": float(np.percentile(boots, 97.5))}

def bootstrap_gradient_ci(ii_low_list, ii_high_list, n_boot=10000, seed=42):
    rng = np.random.RandomState(seed)
    lo = np.array(ii_low_list)
    hi = np.array(ii_high_list)
    n = min(len(lo), len(hi))
    lo, hi = lo[:n], hi[:n]
    point = float(np.median(lo) / np.median(hi)) if np.median(hi) != 0 else None
    boots = np.empty(n_boot)
    for i in range(n_boot):
        idx = rng.randint(0, n, n)
        mh = np.median(hi[idx])
        boots[i] = np.median(lo[idx]) / mh if mh != 0 else np.nan
    boots = boots[~np.isnan(boots)]
    return {"gradient": point, "ci_low": float(np.percentile(boots, 2.5)), "ci_high": float(np.percentile(boots, 97.5)), "n": n}

def compute_stats(values):
    arr = np.array(values)
    n = len(arr)
    if n == 0:
        return {"n": 0}
    return {"n": n, "mean": float(np.mean(arr)), "median": float(np.median(arr)),
            "winsorized_mean_10": float(trim_mean(arr, 0.1)), "std": float(np.std(arr, ddof=1)) if n > 1 else 0.0}

def analyze_experiment(exp_name, results_path, math500_meta):
    per_problem, full_data = load_per_problem_ii(results_path)
    missing_mid, has_mid, missing_high = [], [], []

    for p in per_problem:
        pid = p["problem_id"]
        meta = math500_meta.get(pid, {})
        entry = {"problem_idx": p["problem_idx"], "problem_id": pid,
                 "subject": meta.get("subject", pid.split("/")[1] if "/" in pid else "unknown"),
                 "level": meta.get("level"), "ii_high": p["ii_high"], "ii_mid": p["ii_mid"], "ii_low": p["ii_low"],
                 "n_seg_high": p["n_segments_high"], "n_seg_mid": p["n_segments_mid"], "n_seg_low": p["n_segments_low"],
                 "total_segments": p["n_segments_high"] + p["n_segments_mid"] + p["n_segments_low"]}
        (missing_mid if p["ii_mid"] is None else has_mid).append(entry)
        if p["ii_high"] is None:
            missing_high.append(entry)

    report = {"experiment": exp_name, "n_total": len(per_problem), "n_missing_mid": len(missing_mid), "n_missing_high": len(missing_high)}

    # Task 1: Systematic bias
    report["missing_problems"] = missing_mid
    report["subject_distribution"] = {"missing": dict(Counter(e["subject"] for e in missing_mid)),
                                       "has_data": dict(Counter(e["subject"] for e in has_mid))}
    report["level_distribution"] = {"missing": dict(Counter(e["level"] for e in missing_mid)),
                                     "has_data": dict(Counter(e["level"] for e in has_mid))}

    missing_segs = [e["total_segments"] for e in missing_mid]
    has_segs = [e["total_segments"] for e in has_mid]
    report["segment_count_stats"] = {"missing_mean": float(np.mean(missing_segs)) if missing_segs else None,
                                      "missing_median": float(np.median(missing_segs)) if missing_segs else None,
                                      "has_data_mean": float(np.mean(has_segs)), "has_data_median": float(np.median(has_segs))}
    if len(missing_segs) >= 2 and len(has_segs) >= 2:
        u, pv = mannwhitneyu(missing_segs, has_segs, alternative="two-sided")
        report["segment_count_test"] = {"U": float(u), "p_value": float(pv)}

    # Task 2: Bootstrap N
    ii_h = [p["ii_high"] for p in per_problem if p["ii_high"] is not None]
    ii_m = [p["ii_mid"] for p in per_problem if p["ii_mid"] is not None]
    ii_l = [p["ii_low"] for p in per_problem if p["ii_low"] is not None]
    report["bootstrap_N"] = {"n_high": len(ii_h), "n_mid": len(ii_m), "n_low": len(ii_l),
                              "n_min_for_gradient": min(len(ii_h), len(ii_m), len(ii_l))}

    # Task 3: Robustness
    complete = [p for p in per_problem if all(p[f"ii_{ph}"] is not None for ph in ["high", "mid", "low"])]

    full_stats, sub_stats = {}, {}
    for ph, vals in [("high", ii_h), ("mid", ii_m), ("low", ii_l)]:
        s = compute_stats(vals)
        s.update(bootstrap_median_ci(vals))
        full_stats[ph] = s

    sub_h = [p["ii_high"] for p in complete]
    sub_m = [p["ii_mid"] for p in complete]
    sub_l = [p["ii_low"] for p in complete]
    for ph, vals in [("high", sub_h), ("mid", sub_m), ("low", sub_l)]:
        s = compute_stats(vals)
        s.update(bootstrap_median_ci(vals))
        sub_stats[ph] = s

    report["robustness"] = {
        "n_complete": len(complete),
        "full_set": {"stats": full_stats, "gradient_ci": bootstrap_gradient_ci(ii_l, ii_h)},
        "complete_subset": {"stats": sub_stats, "gradient_ci": bootstrap_gradient_ci(sub_l, sub_h)},
    }
    return report

def format_report(reports):
